import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const artifactPath =
  "artifacts/contracts/XNSSubdomainRegistrar.sol/XNSSubdomainRegistrar.json";
const artifact = JSON.parse(
  fs.readFileSync(path.join(root, artifactPath), "utf8"),
);

if (
  !Array.isArray(artifact.abi) ||
  typeof artifact.bytecode !== "string" ||
  !artifact.bytecode.startsWith("0x") ||
  artifact.bytecode.length <= 2
) {
  throw new Error("Invalid Hardhat artifact for XNSSubdomainRegistrar");
}

const target = path.join(
  root,
  "frontend",
  "generated",
  "apothemSubdomainDeployment.ts",
);
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(
  target,
  [
    "// Generated from Hardhat artifacts during the build.",
    "// Do not edit this file manually.",
    "export const apothemSubdomainDeploymentArtifact = " +
      JSON.stringify({ abi: artifact.abi, bytecode: artifact.bytecode }) +
      " as const;",
    "",
  ].join("\n"),
);
console.log("Generated", path.relative(root, target));
